export class AuditLog {
  #records                = [];
  write(r                                )              {
    const rec              = { id: randomUUID(), at: Date.now(), ...r };
    this.#records.push(rec);
    return rec;
  }
  forRecord(recordId        )                {
    return this.#records.filter((r) => r.recordId === recordId);
  }
  all()                         {
    return this.#records;
  }
}

